const body = $input.first().json.body;

const required = ['recipe_name', 'ingredients', 'serves'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

if (!Array.isArray(body.ingredients) || body.ingredients.length === 0) {
  return [{ json: { valid: false, error: 'ingredients must be a non-empty array' } }];
}

const serves = parseInt(body.serves);
if (isNaN(serves) || serves < 1) {
  return [{ json: { valid: false, error: 'serves must be a positive integer' } }];
}

const targetFoodCostPct = parseFloat(body.target_food_cost_pct) || 30;
const laborCostPerHour = parseFloat(body.labor_cost_per_hour) || 0;
const prepTimeMinutes = parseFloat(body.prep_time_minutes) || 0;
const overheadMultiplier = parseFloat(body.overhead_multiplier) || 1.0;

return [{
  json: {
    valid: true,
    recipeName: body.recipe_name.trim(),
    ingredients: body.ingredients,
    serves,
    targetFoodCostPct,
    laborCostPerHour,
    prepTimeMinutes,
    overheadMultiplier,
    currency: body.currency || 'USD',
    menuContext: body.menu_context || '',
    replyEmail: body.reply_email || null,
    requestedAt: new Date().toISOString()
  }
}];

const input = $input.first().json;

const ingredients = input.ingredients;
let totalIngredientCost = 0;
const costedIngredients = [];

for (const ing of ingredients) {
  const qty = parseFloat(ing.quantity) || 0;
  const unitCost = parseFloat(ing.unit_cost) || 0;
  const packageSize = parseFloat(ing.package_size) || 1;
  const packageCost = parseFloat(ing.package_cost) || 0;

  let lineCost = 0;
  if (unitCost > 0) {
    lineCost = qty * unitCost;
  } else if (packageCost > 0 && packageSize > 0) {
    const derivedUnitCost = packageCost / packageSize;
    lineCost = qty * derivedUnitCost;
  }

  totalIngredientCost += lineCost;
  costedIngredients.push({
    name: ing.name || 'Unknown',
    quantity: qty,
    unit: ing.unit || '',
    unitCost: unitCost || (packageCost / packageSize),
    lineCost: parseFloat(lineCost.toFixed(4)),
    pctOfTotal: 0
  });
}

for (const ci of costedIngredients) {
  ci.pctOfTotal = totalIngredientCost > 0
    ? parseFloat((ci.lineCost / totalIngredientCost * 100).toFixed(1))
    : 0;
}

const laborCost = (input.laborCostPerHour * input.prepTimeMinutes) / 60;
const baseCostPerBatch = totalIngredientCost * input.overheadMultiplier + laborCost;
const costPerServing = baseCostPerBatch / input.serves;

const suggestedPriceAtTarget = costPerServing / (input.targetFoodCostPct / 100);
const suggestedPriceX3 = costPerServing * 3;
const suggestedPriceX35 = costPerServing * 3.5;
const suggestedPriceX4 = costPerServing * 4;

const topIngredients = [...costedIngredients]
  .sort((a, b) => b.lineCost - a.lineCost)
  .slice(0, 3);

return [{
  json: {
    input,
    costedIngredients,
    totals: {
      ingredientCostBatch: parseFloat(totalIngredientCost.toFixed(2)),
      laborCost: parseFloat(laborCost.toFixed(2)),
      overheadAdjustedCost: parseFloat(baseCostPerBatch.toFixed(2)),
      costPerServing: parseFloat(costPerServing.toFixed(4)),
      costPerServingDisplay: parseFloat(costPerServing.toFixed(2))
    },
    pricing: {
      atTargetFoodCostPct: parseFloat(suggestedPriceAtTarget.toFixed(2)),
      at3x: parseFloat(suggestedPriceX3.toFixed(2)),
      at35x: parseFloat(suggestedPriceX35.toFixed(2)),
      at4x: parseFloat(suggestedPriceX4.toFixed(2)),
      targetFoodCostPct: input.targetFoodCostPct
    },
    topCostDrivers: topIngredients
  }
}];

values.content:
Analyze this recipe cost breakdown and give menu pricing advice.

Recipe: {{ $json.input.recipeName }}
Serves: {{ $json.input.serves }}
Menu context: {{ $json.input.menuContext || 'not specified' }}
Currency: {{ $json.input.currency }}

Cost breakdown:
- Ingredient cost (batch): {{ $json.input.currency }}{{ $json.totals.ingredientCostBatch }}
- Labor cost: {{ $json.input.currency }}{{ $json.totals.laborCost }}
- Overhead-adjusted batch cost: {{ $json.input.currency }}{{ $json.totals.overheadAdjustedCost }}
- Cost per serving: {{ $json.input.currency }}{{ $json.totals.costPerServingDisplay }}
- Overhead multiplier applied: {{ $json.input.overheadMultiplier }}x

Suggested prices:
- At {{ $json.pricing.targetFoodCostPct }}% food cost target: {{ $json.input.currency }}{{ $json.pricing.atTargetFoodCostPct }}
- At 3x markup: {{ $json.input.currency }}{{ $json.pricing.at3x }}
- At 3.5x markup: {{ $json.input.currency }}{{ $json.pricing.at35x }}
- At 4x markup: {{ $json.input.currency }}{{ $json.pricing.at4x }}

Top cost drivers:
{{ $json.topCostDrivers.map(i => `- ${i.name}: ${$json.input.currency}${i.lineCost} (${i.pctOfTotal}% of ingredient cost)`).join('\n') }}

Give: (1) which price point you'd recommend and why, (2) whether the cost is competitive for this type of dish, (3) one specific way to reduce cost if needed.
